TgtPattern:
SELECT <col_list>, {for <value>, <alias> in <sample_values>, <alias_list> ADD ', ': SUM(CASE WHEN <aggr_col>=<value> THEN <col> ELSE 0 END) AS <alias>}
FROM <tables: LIST[TABLE]>
GROUP BY <col_list>

SELECT <col_list>, {for <value>, <alias> in <sample_values>, <alias_list> ADD ', ': COUNT(CASE WHEN <aggr_col>=<value> THEN <col> ELSE NULL END) AS <alias>}
FROM <tables: LIST[TABLE]>
GROUP BY <col_list>
